#include "rhodes/event_processor.hpp"
#include <array>
#include <bit>
#include <cstdint>
#include <iostream>
#include <stdexcept>

void word(std::uint64_t& h, std::uint64_t value) {
    for (unsigned shift = 0; shift < 64; shift += 8) {
        h ^= (value >> shift) & 255U;
        h *= 1099511628211ULL;
    }
}
void check(bool ok) { if (!ok) { throw std::runtime_error("trajectory failed"); } }
int main() {
    for (double rate : {48000.0, 192000.0}) {
        for (bool pedal : {true, false}) {
            rhodes::EventProcessor p;
            check(p.prepare(rate));
            std::array<rhodes::EngineEvent, 147> initial{};
            initial[0] = {0, 0, rhodes::EventType::sustain, 0, 1.0};
            for (std::size_t key = 0; key < 73; ++key) {
                initial[1 + key] = {0, static_cast<std::uint32_t>(1 + key),
                    rhodes::EventType::note_on, key, 0.7};
                initial[74 + key] = {0, static_cast<std::uint32_t>(74 + key),
                    rhodes::EventType::note_off, key, 0.0};
            }
            std::array<double, 1> ignored{};
            check(p.process(ignored, initial).succeeded());
            std::uint64_t hash = 14695981039346656037ULL;
            word(hash, std::bit_cast<std::uint64_t>(ignored[0]));
            std::array<double, 64> out{};
            std::array<rhodes::EngineEvent, 256> events{};
            for (std::size_t block = 0; block < 128; ++block) {
                for (std::size_t i = 0; i < events.size(); ++i) {
                    const auto offset = static_cast<std::uint32_t>(block % 2 == 0 ? i / 4 : 0);
                    const auto type = pedal ? rhodes::EventType::sustain :
                        i % 2 == 0 ? rhodes::EventType::note_off : rhodes::EventType::note_on;
                    events[i] = {offset, static_cast<std::uint32_t>(i), type,
                        pedal ? 0 : (block * 128 + i / 2) % 73,
                        pedal ? static_cast<double>(i % 2) : i % 2 == 0 ? 0.0 : 0.7};
                }
                check(p.process(out, events).succeeded());
                for (double sample : out) { word(hash, std::bit_cast<std::uint64_t>(sample)); }
            }
            for (std::size_t key = 0; key < 73; ++key) {
                for (std::size_t mode = 0; mode < 3; ++mode) {
                    const auto state = p.engine().modal_state(key, mode);
                    check(state.has_value());
                    word(hash, std::bit_cast<std::uint64_t>(state->displacement_m));
                    word(hash, std::bit_cast<std::uint64_t>(state->velocity_m_per_s));
                }
            }
            word(hash, std::bit_cast<std::uint64_t>(p.engine().mechanical_energy_joules()));
            std::cout << rate << ' ' << pedal << ' ' << std::hex << hash << std::dec << '\n';
        }
    }
}
